module traffic_light_time (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [7:0] t_0, t_1, t_2, t_3, t_4, t_5, t_6, t_7, t_8, t_9, t_10, t_11, t_12, t_13, t_14,\n    input wire [7:0] g_0, g_1, g_2, g_3, g_4, g_5, g_6, g_7, g_8, g_9, g_10, g_11, g_12, g_13, g_14,\n    input wire [7:0] r_0, r_1, r_2, r_3, r_4, r_5, r_6, r_7, r_8, r_9, r_10, r_11, r_12, r_13, r_14,\n    output reg [31:0] total_time,\n    output reg done\n);\n\n    localparam [31:0] SQRT_2000 = 32'd2930012;\n    localparam MAX_VELOCITY = 8'd200;\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] LOAD_LIGHT = 3'd1;\n    localparam [2:0] COMPUTE_SEG = 3'd2;\n    localparam [2:0] CHECK_GREEN = 3'd3;\n    localparam [2:0] WAIT_GREEN = 3'd4;\n    localparam [2:0] NEXT_LIGHT = 3'd5;\n    localparam [2:0] FINAL_SEG = 3'd6;\n    localparam [2:0] DONE_STATE = 3'd7;\n\n    reg [2:0] state;\n    reg [3:0] light_idx;\n    reg [31:0] current_time;\n    reg [31:0] current_velocity;\n    reg [31:0] seg_time;\n    reg [31:0] arrival_time;\n    reg [31:0] period_fp;\n    reg [31:0] t_fp;\n    reg [31:0] green_end_fp;\n    reg [31:0] phase;\n    reg [31:0] wait_time;\n\n    reg [31:0] sqrt_lut [0:200];\n    integer i;\n\n    function [31:0] get_sqrt_time;\n        input [31:0] vel;\n        integer vel_int;\n        begin\n            vel_int = vel[31:16];\n            if (vel_int > MAX_VELOCITY) vel_int = MAX_VELOCITY;\n            get_sqrt_time = sqrt_lut[vel_int];\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            total_time <= 32'd0;\n            current_time <= 32'd0;\n            current_velocity <= 32'd0;\n            light_idx <= 4'd0;\n            seg_time <= 32'd0;\n            arrival_time <= 32'd0;\n            period_fp <= 32'd0;\n            t_fp <= 32'd0;\n            green_end_fp <= 32'd0;\n            phase <= 32'd0;\n            wait_time <= 32'd0;\n            for (i = 0; i <= MAX_VELOCITY; i = i + 1) \n                sqrt_lut[i] <= 32'd0;\n            sqrt_lut[0] <= SQRT_2000;\n            sqrt_lut[1] <= 32'd1465006;\n            sqrt_lut[2] <= 32'd977216;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        if (n == 4'd1) state <= FINAL_SEG;\n                        else state <= LOAD_LIGHT;\n                        light_idx <= 4'd0;\n                        current_time <= 32'd0;\n                        current_velocity <= 32'd0;\n                    end\n                end\n\n                LOAD_LIGHT: begin\n                    case (light_idx)\n                        4'd0: begin t_fp <= t_0 * 32'd65536; period_fp <= (g_0 + r_0) * 32'd65536; green_end_fp <= (t_0 + g_0) * 32'd65536; end\n                        4'd1: begin t_fp <= t_1 * 32'd65536; period_fp <= (g_1 + r_1) * 32'd65536; green_end_fp <= (t_1 + g_1) * 32'd65536; end\n                        4'd2: begin t_fp <= t_2 * 32'd65536; period_fp <= (g_2 + r_2) * 32'd65536; green_end_fp <= (t_2 + g_2) * 32'd65536; end\n                        4'd3: begin t_fp <= t_3 * 32'd65536; period_fp <= (g_3 + r_3) * 32'd65536; green_end_fp <= (t_3 + g_3) * 32'd65536; end\n                        4'd4: begin t_fp <= t_4 * 32'd65536; period_fp <= (g_4 + r_4) * 32'd65536; green_end_fp <= (t_4 + g_4) * 32'd65536; end\n                        4'd5: begin t_fp <= t_5 * 32'd65536; period_fp <= (g_5 + r_5) * 32'd65536; green_end_fp <= (t_5 + g_5) * 32'd65536; end\n                        4'd6: begin t_fp <= t_6 * 32'd65536; period_fp <= (g_6 + r_6) * 32'd65536; green_end_fp <= (t_6 + g_6) * 32'd65536; end\n                        4'd7: begin t_fp <= t_7 * 32'd65536; period_fp <= (g_7 + r_7) * 32'd65536; green_end_fp <= (t_7 + g_7) * 32'd65536; end\n                        4'd8: begin t_fp <= t_8 * 32'd65536; period_fp <= (g_8 + r_8) * 32'd65536; green_end_fp <= (t_8 + g_8) * 32'd65536; end\n                        4'd9: begin t_fp <= t_9 * 32'd65536; period_fp <= (g_9 + r_9) * 32'd65536; green_end_fp <= (t_9 + g_9) * 32'd65536; end\n                        4'd10: begin t_fp <= t_10 * 32'd65536; period_fp <= (g_10 + r_10) * 32'd65536; green_end_fp <= (t_10 + g_10) * 32'd65536; end\n                        4'd11: begin t_fp <= t_11 * 32'd65536; period_fp <= (g_11 + r_11) * 32'd65536; green_end_fp <= (t_11 + g_11) * 32'd65536; end\n                        4'd12: begin t_fp <= t_12 * 32'd65536; period_fp <= (g_12 + r_12) * 32'd65536; green_end_fp <= (t_12 + g_12) * 32'd65536; end\n                        4'd13: begin t_fp <= t_13 * 32'd65536; period_fp <= (g_13 + r_13) * 32'd65536; green_end_fp <= (t_13 + g_13) * 32'd65536; end\n                        4'd14: begin t_fp <= t_14 * 32'd65536; period_fp <= (g_14 + r_14) * 32'd65536; green_end_fp <= (t_14 + g_14) * 32'd65536; end\n                    endcase\n                    state <= COMPUTE_SEG;\n                end\n\n                COMPUTE_SEG: begin\n                    if (current_velocity == 32'd0) seg_time <= SQRT_2000;\n                    else seg_time <= get_sqrt_time(current_velocity);\n                    arrival_time <= current_time + seg_time;\n                    state <= CHECK_GREEN;\n                end\n\n                CHECK_GREEN: begin\n                    if (arrival_time < period_fp) begin\n                        phase <= arrival_time;\n                        if ((phase >= t_fp) && (phase <= green_end_fp)) begin\n                            current_velocity <= current_velocity + 32'd65536;\n                            current_time <= arrival_time;\n                            state <= NEXT_LIGHT;\n                        end else begin\n                            if (t_fp >= phase) wait_time <= t_fp - phase;\n                            else wait_time <= t_fp + period_fp - phase;\n                            state <= WAIT_GREEN;\n                        end\n                    end else begin\n                        phase <= arrival_time;\n                        state <= WAIT_GREEN;\n                    end\n                end\n\n                WAIT_GREEN: begin\n                    if (phase >= period_fp) begin\n                        phase <= phase - period_fp;\n                        if (phase >= period_fp) begin\n                            state <= WAIT_GREEN;\n                        end else begin\n                            arrival_time <= phase;\n                            state <= CHECK_GREEN;\n                        end\n                    end else begin\n                        current_time <= current_time + wait_time;\n                        current_velocity <= 32'd0;\n                        state <= NEXT_LIGHT;\n                    end\n                end\n\n                NEXT_LIGHT: begin\n                    light_idx <= light_idx + 4'd1;\n                    if (light_idx >= (n - 4'd2)) state <= FINAL_SEG;\n                    else state <= LOAD_LIGHT;\n                end\n\n                FINAL_SEG: begin\n                    if (current_velocity == 32'd0) seg_time <= SQRT_2000;\n                    else seg_time <= get_sqrt_time(current_velocity);\n                    total_time <= current_time + seg_time;\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule